module Rubyboy
  class Registers
    attr_reader :a, :b, :c, :d, :e, :h, :l, :f

    def initialize
      @a = 0x01
      @b = 0x00
      @c = 0x13
      @d = 0x00
      @e = 0xd8
      @h = 0x01
      @l = 0x4d
      @f = 0xb0
    end

    def a=(value)
      @a = value & 0xff
    end

    def b=(value)
      @b = value & 0xff
    end

    def c=(value)
      @c = value & 0xff
    end

    def d=(value)
      @d = value & 0xff
    end

    def e=(value)
      @e = value & 0xff
    end

    def h=(value)
      @h = value & 0xff
    end

    def l=(value)
      @l = value & 0xff
    end

    def f=(value)
      @f = value & 0xf0
    end

    def af
      (@a << 8) | @f
    end

    def bc
      (@b << 8) | @c
    end

    def de
      (@d << 8) | @e
    end

    def hl
      (@h << 8) | @l
    end

    def af=(value)
      @a = (value >> 8) & 0xff
      @f = value & 0xf0
    end

    def bc=(value)
      @b = (value >> 8) & 0xff
      @c = value & 0xff
    end

    def de=(value)
      @d = (value >> 8) & 0xff
      @e = value & 0xff
    end

    def hl=(value)
      @h = (value >> 8) & 0xff
      @l = value & 0xff
    end
  end
